/** Helper structures for the Collada loader */

#ifndef AI_COLLADAHELPER_H_INC
#define AI_COLLADAHELPER_H_INC

#include <assimp/light.h>
#include <assimp/material.h>
#include <assimp/mesh.h>

#include <cstdint>
#include <map>
#include <set>
#include <vector>

struct aiMaterial;

namespace Assimp {
namespace Collada {

/// Collada file versions which evolved during the years ...
enum FormatVersion {
    FV_1_5_n,
    FV_1_4_n,
    FV_1_3_n
};

/// Transformation types that can be applied to a node
enum TransformType {
    TF_LOOKAT,
    TF_ROTATE,
    TF_TRANSLATE,
    TF_SCALE,
    TF_SKEW,
    TF_MATRIX
};

/// Different types of input data to a vertex or face
enum InputType {
    IT_Invalid,
    IT_Vertex, // special type for per-index data referring to the <vertices> element carrying the per-vertex data.
    IT_Position,
    IT_Normal,
    IT_Texcoord,
    IT_Color,
    IT_Tangent,
    IT_Bitangent
};

/// Supported controller types
enum ControllerType {
    Skin,
    Morph
};

/// Supported morph methods
enum MorphMethod {
    Normalized,
    Relative
};

/// Common metadata keys as <Collada, Assimp>
using MetaKeyPair = std::pair<std::string, std::string>;
using MetaKeyPairVector = std::vector<MetaKeyPair>;

/// Collada as lower_case (native)
const MetaKeyPairVector &GetColladaAssimpMetaKeys();

// Collada as CamelCase (used by Assimp for consistency)
const MetaKeyPairVector &GetColladaAssimpMetaKeysCamelCase();

/// Convert underscore_separated to CamelCase "authoring_tool" becomes "AuthoringTool"
void ToCamelCase(std::string &text);

/// Contains all data for one of the different transformation types
struct Transform {
    std::string mID; ///< SID of the transform step, by which anim channels address their target node
    TransformType mType;
    ai_real f[16]; ///< Interpretation of data depends on the type of the transformation
};

/// A collada camera.
struct Camera {
    Camera() :
            mOrtho(false),
            mHorFov(10e10f),
            mVerFov(10e10f),
            mAspect(10e10f),
            mZNear(0.1f),
            mZFar(1000.f) {}

    /// Name of camera
    std::string mName;

    /// True if it is an orthographic camera
    bool mOrtho;

    /// Horizontal field of view in degrees
    ai_real mHorFov;

    /// Vertical field of view in degrees
    ai_real mVerFov;

    /// Screen aspect
    ai_real mAspect;

    /// Near& far z
    ai_real mZNear, mZFar;
};

#define ASSIMP_COLLADA_LIGHT_ANGLE_NOT_SET 1e9f

/** A collada light source. */
struct Light {
    Light() :
            mType(aiLightSource_UNDEFINED),
            mAttConstant(1.f),
            mAttLinear(0.f),
            mAttQuadratic(0.f),
            mFalloffAngle(180.f),
            mFalloffExponent(0.f),
            mPenumbraAngle(ASSIMP_COLLADA_LIGHT_ANGLE_NOT_SET),
            mOuterAngle(ASSIMP_COLLADA_LIGHT_ANGLE_NOT_SET),
            mIntensity(1.f) {}

    /// Type of the light source aiLightSourceType + ambient
    unsigned int mType;

    /// Color of the light
    aiColor3D mColor;

    /// Light attenuation
    ai_real mAttConstant, mAttLinear, mAttQuadratic;

    /// Spot light falloff
    ai_real mFalloffAngle;
    ai_real mFalloffExponent;

    // -----------------------------------------------------
    // FCOLLADA extension from here

    /// ... related stuff from maja and max extensions
    ai_real mPenumbraAngle;
    ai_real mOuterAngle;

    /// Common light intensity
    ai_real mIntensity;
};

/** Short vertex index description */
struct InputSemanticMapEntry {
    InputSemanticMapEntry() :
            mSet(0),
            mType(IT_Invalid) {}

    /// Index of set, optional
    unsigned int mSet;

    /// Type of referenced vertex input
    InputType mType;
};

/// Table to map from effect to vertex input semantics
struct SemanticMappingTable {
    /// Name of material
    std::string mMatName;

    /// List of semantic map commands, grouped by effect semantic name
    using InputSemanticMap = std::map<std::string, InputSemanticMapEntry>;
    InputSemanticMap mMap;

    /// For std::find
    bool operator==(const std::string &s) const {
        return s == mMatName;
    }
};

